import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { blogApi } from '../api/blog';
import { BlogPost } from '../types';
import { DEFAULT_BLOG_POSTS, IMAGES } from '../constants';
import { Search, ArrowRight, BookOpen, Loader2 } from 'lucide-react';

const BlogList: React.FC = () => {
  const [posts, setPosts] = useState<BlogPost[]>(DEFAULT_BLOG_POSTS);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        const data = await blogApi.getAllPublic();
        if (data && data.length > 0) {
          const remoteSlugs = new Set(data.map(p => p.slug));
          setPosts([...data, ...DEFAULT_BLOG_POSTS.filter(p => !remoteSlugs.has(p.slug))]);
        } else {
          setPosts(DEFAULT_BLOG_POSTS);
        }
      } catch {
        setPosts(DEFAULT_BLOG_POSTS);
      } finally {
        setIsLoading(false);
      }
    };
    fetchPosts();
  }, []);

  const filteredPosts = posts.filter(
    post =>
      post.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      post.summary.toLowerCase().includes(searchQuery.toLowerCase()) ||
      post.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pt-28 pb-24 transition-colors duration-200">
      <div className="max-w-[1360px] mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Header */}
        <div className="pb-12 mb-12 border-b border-[#E4E4DE] dark:border-[#222630] flex flex-col lg:flex-row lg:items-end justify-between gap-8">
          <div className="max-w-2xl">
            <div className="text-xs text-emerald-700 dark:text-emerald-400 font-medium mb-2">
              Technical Briefings · Architecture Notes · Quantitative Research
            </div>
            <h1 className="font-display text-3xl sm:text-5xl font-bold text-slate-900 dark:text-white tracking-tight mb-4">
              The Quader Engineering Journal
            </h1>
            <p className="text-base text-slate-600 dark:text-slate-400 leading-relaxed">
              Architectural deep dives into low-latency MQL5 execution bridges, multi-tenant SaaS infrastructure, and modern web engineering by Alireza Kiani.
            </p>
          </div>

          <div className="relative w-full lg:w-80">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input
              type="text"
              placeholder="Filter articles by topic or stack..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full h-11 pl-10 pr-4 bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:border-emerald-600"
            />
          </div>
        </div>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <Loader2 className="animate-spin text-emerald-600" size={28} />
            <p className="text-xs text-slate-500">Loading Engineering Briefings...</p>
          </div>
        ) : filteredPosts.length === 0 ? (
          <div className="text-center py-20 bg-white dark:bg-[#111318] rounded-2xl border border-[#E4E4DE] dark:border-[#222630]">
            <BookOpen className="mx-auto text-slate-400 mb-3" size={32} />
            <h3 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-1">
              No matching articles
            </h3>
            <p className="text-xs text-slate-500">Try clearing your search filter.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredPosts.map(post => (
              <article
                key={post._id}
                className="group bg-white dark:bg-[#111318] rounded-2xl overflow-hidden border border-[#E4E4DE] dark:border-[#222630] hover:border-slate-400 dark:hover:border-slate-700 transition-all duration-200 hover:-translate-y-0.5 flex flex-col"
              >
                <Link
                  to={`/blog/${post.slug}`}
                  className="relative aspect-[16/10] overflow-hidden bg-[#F3F3EE] dark:bg-[#171A21] block border-b border-[#E4E4DE] dark:border-[#222630]"
                >
                  <img
                    src={post.coverImageUrl || IMAGES.quantEngine}
                    alt={post.title}
                    referrerPolicy="no-referrer"
                    className="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-300"
                  />
                </Link>

                <div className="p-6 flex-1 flex flex-col">
                  {/* Unboxed Metadata */}
                  <div className="flex items-center gap-2 text-xs text-slate-500 dark:text-slate-400 mb-3">
                    <span>{post.tags[0] || 'Architecture'}</span>
                    <span aria-hidden="true">·</span>
                    <span>
                      {new Date(post.createdAt).toLocaleDateString('en-US', {
                        year: 'numeric',
                        month: 'short',
                        day: 'numeric'
                      })}
                    </span>
                    <span aria-hidden="true">·</span>
                    <span>Alireza Kiani</span>
                  </div>

                  <Link
                    to={`/blog/${post.slug}`}
                    className="font-display text-lg font-bold text-slate-900 dark:text-white mb-3 group-hover:text-emerald-600 dark:group-hover:text-emerald-400 transition-colors line-clamp-2 leading-snug"
                  >
                    {post.title}
                  </Link>

                  <p className="text-sm text-slate-600 dark:text-slate-400 mb-6 line-clamp-3 leading-relaxed flex-1">
                    {post.summary}
                  </p>

                  <div className="pt-4 border-t border-[#E4E4DE] dark:border-[#222630] flex items-center justify-between text-xs">
                    <span className="text-slate-500 dark:text-slate-400 truncate max-w-[180px]">
                      {post.tags.slice(0, 3).join(' · ')}
                    </span>
                    <Link
                      to={`/blog/${post.slug}`}
                      className="inline-flex items-center gap-1.5 font-semibold text-emerald-600 dark:text-emerald-400 hover:underline shrink-0"
                    >
                      <span>Read Briefing</span>
                      <ArrowRight size={14} />
                    </Link>
                  </div>
                </div>
              </article>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default BlogList;
